import sys,json
for line in sys.stdin.buffer.read().decode('utf-8',errors='replace').splitlines():
    line=line.strip()
    if not line: continue
    try: e=json.loads(line)
    except Exception: continue
    def shape(o,d=0):
        if isinstance(o,dict): return {k:shape(v,d+1) if d<2 else type(v).__name__ for k,v in o.items()}
        if isinstance(o,list): return [shape(o[0],d+1)] if o else []
        s=str(o); return s[:60]
    print(json.dumps(shape(e))[:500])
